// convertTool0Result validates the returned service value and separates content from
// structured JSON and host metadata. A service-selected view keeps each output
// within that view, and host metadata never enters structured model output.
func convertTool0Result(result *chorus.TextResult) ([]*ContentItem, json.RawMessage, json.RawMessage, error) {
	if err := mcpcodec.ValidateJoinResultValue(result); err != nil {
		return nil, nil, nil, err
	}
	content := []*ContentItem{}
	metadata := resultMeta()
	for _, value := range result.Content {
		item, err := convertTool0View0Content(value.Content)
		if err != nil {
			return nil, nil, nil, err
		}
		content = append(content, item)
	}
	return content, nil, metadata, nil
}

