// convertTool0View0Content checks the selected service content branch and converts its fields
// to MCP. An unset branch or missing selected value returns a validation error.
func convertTool0View0Content(value chorus.Content) (*ContentItem, error) {

	if err := value.Validate(); err != nil {
		return nil, err
	}
	switch value.Kind() {

	case chorus.ContentKindText:
		selected, _ := value.AsText()

		out := &ContentItem{
			Text: &selected.Text,
		}

		out.Type = "text"

		return out, nil

	default:
		panic("content reached conversion without validation")
	}
}

